def parse_kv(s: str) -> dict:
    """
    Parses a string in the format 'key1=value1; key2=value2' into a dictionary.
    Semicolons separate pairs; the first '=' separates key from value;
    keys and values are whitespace-trimmed; a backslash-escaped semicolon \;
    is a literal semicolon in a value. An empty string yields an empty dict.
    """
    if not s:
        return {}

    # Replace escaped semicolons (\\;) with a unique placeholder
    # so they are not split when splitting by ';'
    placeholder = "___ESC_SEMICOLON___"
    temp_s = s.replace('\\;', placeholder)

    # Split into pairs by semicolon
    pairs = temp_s.split(';')
    result = {}

    for pair in pairs:
        if '=' not in pair:
            continue

        # Split by the first '='
        parts = pair.split('=', 1)
        key = parts[0].strip()

        if len(parts) == 1:
            continue # Should not happen if '=' is in pair

        value = parts[1].strip()

        # Restore placeholder back to literal semicolon
        value = value.replace(placeholder, ';')

        if key:
            result[key] = value

    return result

