import pytest
from parse_kv import parse_kv

def test_empty_string():
    assert parse_kv("") == {}

def test_simple_case():
    assert parse_kv("key1=value1; key2=value2") == {"key1": "value1", "key2": "value2"}

def test_whitespace_trimming():
    assert parse_kv("  key1 = value1 ; key2= value2  ") == {"key1": "value1", "key2": "value2"}

def test_key_and_value_with_spaces():
    assert parse_kv("  my key =  some value ") == {"my key": "some value"}

def test_escaped_semicolon():
    # Value containing a literal semicolon escaped as \;
    test_string = "key1=value1\\;part2; key2=value2"
    expected = {"key1": "value1;part2", "key2": "value2"}
    assert parse_kv(test_string) == expected

def test_complex_mixed_cases():
    # Mix of simple, spaces, and escaped semicolons
    test_string = "  k1 = v1\\;p2; k2= v2; k3=v3 "
    expected = {"k1": "v1;p2", "k2": "v2", "k3": "v3"}
    assert parse_kv(test_string) == expected

def test_only_whitespace():
    # Should treat leading/trailing/internal whitespace as keys or values as intended by the logic
    assert parse_kv("  ; ; ") == {}

def test_multiple_equals():
    # Ensure only the first '=' splits key/value
    assert parse_kv("key=value=with=equals") == {"key": "value=with=equals"}

def test_invalid_pairs():
    # Should ignore pairs without '='
    assert parse_kv("valid=pair; invalid_pair; another=valid") == {"valid": "pair", "another": "valid"}

